    for(var j in S.spese){ var s=S.spese[j]; if(num(s.totale)===null||isNs(s)) continue; var sc2=S.scali[s.scalo]||{}; pagamentiDi(s).forEach(function(p){ if(!num(p.importo)) return; mov.push({d:p.data||s.dataPagamento||"",tipo:isComm(s)?"Incasso ns commissione":"Pagamento",chi:s.fornitore,sc:sc2,banca:p.modo||s.modo||"",entrata:isComm(s)?num(p.importo):0,uscita:isComm(s)?0:num(p.importo),note:(s.numFattura?"fatt. "+s.numFattura+" ":"")+(p.note||s.descrizione||"")}); }); }
    for(var c in S.cassa||{}){ var cm=S.cassa[c], ci=num(cm.importo)||0; if(!ci||(cm.tipo!=="prelievo"&&cm.tipo!=="versamento")) continue; mov.push({d:cm.data||"",tipo:cm.tipo==="prelievo"?"Prelievo per cassa":"Versamento da cassa",chi:"Cassa",sc:{},banca:nomeBanca(cm.banca),entrata:cm.tipo==="versamento"?ci:0,uscita:cm.tipo==="prelievo"?ci:0,note:cm.note||cm.descr||""}); }
    mov.forEach(function(m){ anni[anno(m.d)]=1; }); mov=mov.filter(function(m){ return (!S.ct.anno||anno(m.d)===S.ct.anno)&&(!S.ct.mese||ym(m.d)===S.ct.mese)&&(!S.ct.banca||m.banca===S.ct.banca); });
    mov.sort(function(a,b){ return (a.d||"").localeCompare(b.d||"")||a.tipo.localeCompare(b.tipo); });
    var te=0,tu=0,perMese={},banche={}; mov.forEach(function(m){ te+=m.entrata; tu+=m.uscita; var a=perMese[ym(m.d)||"—"]||(perMese[ym(m.d)||"—"]={e:0,u:0}); a.e+=m.entrata; a.u+=m.uscita; if(m.banca) banche[m.banca]=1; });
