    for(var q in S.scali){ var sc3=S.scali[q]; (sc3.incassi||[]).forEach(function(i){ var ii=num(i.importo); if(!ii||i.banca!=="cassa") return; mov.push({id:"",d:i.data||"",tipo:"entrata",chi:clienteDi(sc3),descr:"Incasso in contanti "+(sc3.nave||""),cat:"Incassi",sc:sc3,entrata:ii,uscita:0,fda:false,note:i.note||"",auto:true,ord:""}); }); }
